"""URL slugs for titles."""
import re
import unicodedata


def _base_slug(title):
    """Return the untruncated, normalized slug for *title*."""
    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    slug = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return slug or "untitled"


def _limit_slug(slug, max_length):
    """Limit a slug to whole leading words, cutting the first word if needed."""
    if max_length is None or len(slug) <= max_length:
        return slug

    words = slug.split("-")
    if len(words[0]) > max_length:
        return words[0][:max_length]

    result = words[0]
    for word in words[1:]:
        candidate = result + "-" + word
        if len(candidate) > max_length:
            break
        result = candidate
    return result


def slugify(title, max_length=None):
    """Lower-case ASCII words joined by hyphens, optionally length-limited."""
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")
    return _limit_slug(_base_slug(title), max_length)


def unique_slug(title, taken, max_length=None):
    """Return a slug that is not present in *taken*."""
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")

    base = _base_slug(title)
    candidate = _limit_slug(base, max_length)
    if candidate not in taken:
        return candidate

    number = 2
    while True:
        suffix = "-" + str(number)
        if max_length is not None:
            available = max_length - len(suffix)
            if available < 1:
                raise ValueError("max_length leaves no room for the slug")
            shortened = _limit_slug(base, available)
            candidate = shortened + suffix
        else:
            candidate = base + suffix
        if candidate not in taken:
            return candidate
        number += 1
